def solve(gi,go=None):
    g=[r[:] for r in gi]; h=len(g); w=len(g[0])
    # background = most common color
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    def box(r,c,color):
        if not(0<=r<h and 0<=c<w) or g[r][c]!=color: return None
        top=r; while top+1<h and all(g[top+1][k]==color for k in range(c,c+7)): top+=1
        left=c
        while left-1>=0 and all(g[k][left-1]==color for k in range(top,top+8)): left-=1
        return (top,left)
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and g[r][c]!=0 and not seen[r][c]:
                col=g[r][c]
                if box(r,c,col): pass
                # find bounding box of this component
                comp=[(r,c)]; stack=[(r,c)]; 
                while stack:
                    a,b=stack.pop()
                    if 0<=a<h and 0<=b<w and g[a][b]==col and not seen[a][b]:
                        seen[a][b]=True; comp.append((a,b))
                        for da in(-1,0,1):
                            for db in(-1,0,1):
                                if (da,db)!=(0,0): stack.append((a+da,b+db))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                if len(comp)==2*(r1-r0)+2*(c1-c0)-4 and (r1-r0)>=3 and (c1-c0)>=3:
                    # hollow rectangle
                    for a in range(r0+1,r1):
                        for b in range(c0+1,c1):
                            if g[a][b]==col: continue
                            g[a][b]=col+2
    return g
