def solve(gi):
    g=[r[:] for r in gi]; h=len(g); w=len(g[0])
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg: continue
    # simpler: find hollow rectangles by connected components of non-bg color
    seen=set()
    for r in range(h):
        for c in range(w):
            col=g[r][c]
            if col==bg or (r,c) in seen: continue
            comp=[(r,c)]; st=[(r,c)]
            while st:
                a,b=st.pop()
                if (a,b) in seen: continue
                seen.add((a,b))
                comp.append((a,b))
                for da in(-1,0,1):
                    for db in(-1,0,1):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and g[x][y]==col: st.append((x,y))
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            if len(comp)==2*(r1-r0+1)+2*(c1-c0)-4 and r1-r0>=3 and c1-c0>=3:
                fill = 7 if (r1-r0==3 and c1-c0==3) else (col+2 if False else None)
                # decide fill: demo says small box -> 7? check mapping. Try: fill=2 unless box is the tiny 3x3 which gets 7.
                if r1-r0==3 and c1-c0==3: f=7
                else: f=2
                for a in range(r0+1,r1):
                    for b in range(c0+1,c1):
                        if g[a][b]!=col: g[a][b]=f
    return g
